{"file_path":"src/diff.js","content":"/**
 * Diff a side against the base using a longest common subsequence over whole
 * lines, with the earliest-match tie-break the spec describes.
 *
 * Returns a list of changes, each `{ baseStart, baseEnd, sideStart, sideEnd, side }`
 * describing a run of base lines (baseStart..baseEnd) replaced by a run of
 * that side's lines (sideStart..sideEnd). `side` is the string passed in
 * (`'mine'` or `'theirs'`).
 */
export function diffAgainstBase(base, side, sideName) {
  const n = base.length
  const m = side.length

  // dp[i][j] = length of the LCS of base[i:] and side[j:].
  const dp = []
  for (let i = 0; i <= n; i++) dp.push(new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    const dpi = dp[i]
    const dpi1 = dp[i + 1]
    for (let j = m - 1; j >= 0; j--) {
      if (base[i] === side[j]) {
        dpi[j] = dpi1[j + 1] + 1
      } else {
        const a = dpi1[j]
        const b = dpi[j + 1]
        dpi[j] = a >= b ? a : b
      }
    }
  }

  const changes = []
  let i = 0
  let j = 0
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      i++
      j++
      continue
    }
    const baseStart = i
    const sideStart = j
    while (i < n && j < m && base[i] !== side[j]) {
      if (dp[i + 1][j] >= dp[i][j + 1]) {
        i++
      } else {
        j++
      }
    }
    if (i >= n) {
      j = m
    } else if (j >= m) {
      i = n
    }
    changes.push({ baseStart, baseEnd: i, sideStart, sideEnd: j, side: sideName })
  }
  return changes
}
"}

