{"file_path":"src/regions.js","content":"import { diffAgainstBase } from './diff.js'

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

function mergeChanges(mineChanges, theirsChanges) {
  const result = []
  let i = 0
  let j = 0
  while (i < mineChanges.length && j < theirsChanges.length) {
    if (mineChanges[i].baseStart <= theirsChanges[j].baseStart) {
      result.push(mineChanges[i++])
    } else {
      result.push(theirsChanges[j++])
    }
  }
  while (i < mineChanges.length) result.push(mineChanges[i++])
  while (j < theirsChanges.length) result.push(theirsChanges[j++])
  return result
}

function groupIntoRegions(changes) {
  const regions = []
  let i = 0
  while (i < changes.length) {
    const group = [changes[i]]
    let baseStart = changes[i].baseStart
    let baseEnd = changes[i].baseEnd
    let j = i + 1
    while (j < changes.length && changes[j].baseStart <= baseEnd) {
      group.push(changes[j])
      if (changes[j].baseEnd > baseEnd) baseEnd = changes[j].baseEnd
      j++
    }
    regions.push({ baseStart, baseEnd, changes: group })
    i = j
  }
  return regions
}

function computeSideLines(base, sideArray, region, sideChanges) {
  if (sideChanges.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const minC = sideChanges[0]
  const maxC = sideChanges.reduce((a, b) => (b.baseEnd > a.baseEnd ? b : a), sideChanges[0])
  const prefix = base.slice(region.baseStart, minC.baseStart)
  const middle = sideArray.slice(minC.sideStart, maxC.sideEnd)
  const suffix = base.slice(maxC.baseEnd, region.baseEnd)
  return prefix.concat(middle, suffix)
}

/**
 * Compute the list of merge regions for the three documents.
 *
 * Each region is one of:
 *   { type: 'stable', lines }
 *   { type: 'mine' | 'theirs' | 'both', lines }
 *   { type: 'conflict', mine, base, theirs }
 */
export function computeRegions(mine, base, theirs) {
  const mineChanges = diffAgainstBase(base, mine, 'mine')
  const theirsChanges = diffAgainstBase(base, theirs, 'theirs')
  const merged = mergeChanges(mineChanges, theirsChanges)
  const groups = groupIntoRegions(merged)

  const regions = []
  let cursor = 0

  for (const group of groups) {
    if (group.baseStart > cursor) {
      regions.push({ type: 'stable', lines: base.slice(cursor, group.baseStart) })
    }

    const mineChangesInRegion = group.changes.filter(c => c.side === 'mine')
    const theirsChangesInRegion = group.changes.filter(c => c.side === 'theirs')

    const mineLines = computeSideLines(base, mine, group, mineChangesInRegion)
    const theirsLines = computeSideLines(base, theirs, group, theirsChangesInRegion)
    const baseLines = base.slice(group.baseStart, group.baseEnd)

    if (arraysEqual(mineLines, theirsLines)) {
      regions.push({ type: 'both', lines: mineLines })
    } else if (arraysEqual(mineLines, baseLines)) {
      regions.push({ type: 'theirs', lines: theirsLines })
    } else if (arraysEqual(theirsLines, baseLines)) {
      regions.push({ type: 'mine', lines: mineLines })
    } else {
      regions.push({ type: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines })
    }

    cursor = group.baseEnd
  }

  if (cursor < base.length) {
    regions.push({ type: 'stable', lines: base.slice(cursor, base.length) })
  }

  return regions
}
"}

